// Pure logic for Word scramble (no React), so it can be unit tested.
// Data: content/games/words.json, generated by tools/src/games/words-gen.ts.

export type Puzzle = {
  id: string;
  /** UPPERCASE letters, shuffled so they differ from every accepted word. */
  scramble: string;
  answer: string;
  /** Every word in the list that is an anagram of the same letters (includes `answer`). */
  accept: string[];
  clue: string;
  level: 1 | 2 | 3;
};

export const ROUND_LENGTH = 8;
/** Difficulty ramp for one round of 8 words. */
export const ROUND_LEVELS: (1 | 2 | 3)[] = [1, 1, 2, 2, 2, 3, 3, 3];

export type Rng = () => number;

const modules = import.meta.glob("../../../../content/games/words.json", { eager: true, import: "default" }) as Record<
  string,
  { puzzles?: Puzzle[] }
>;

/** All bundled puzzles; empty (never throws) if the file is missing or malformed. */
export function loadPuzzles(): Puzzle[] {
  try {
    const first = Object.values(modules)[0];
    return Array.isArray(first?.puzzles) ? first.puzzles : [];
  } catch {
    return [];
  }
}

export function shuffle<T>(items: readonly T[], rng: Rng): T[] {
  const out = [...items];
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [out[i], out[j]] = [out[j]!, out[i]!];
  }
  return out;
}

/**
 * Picks 8 puzzles ramping from level 1 to 3. Two puzzles from the same anagram family (LISTEN/SILENT)
 * never appear in one round. If a level runs short, it borrows from the nearest other level.
 */
export function buildRound(puzzles: readonly Puzzle[], rng: Rng, levels: readonly (1 | 2 | 3)[] = ROUND_LEVELS): Puzzle[] {
  const picked: Puzzle[] = [];
  const usedIds = new Set<string>();
  const usedAnswers = new Set<string>();
  for (const level of levels) {
    const order = [level, ...[1, 2, 3].filter((l) => l !== level).sort((a, b) => Math.abs(a - level) - Math.abs(b - level))];
    let chosen: Puzzle | undefined;
    for (const l of order) {
      chosen = shuffle(
        puzzles.filter((p) => p.level === l && !usedIds.has(p.id) && !p.accept.some((w) => usedAnswers.has(w))),
        rng,
      )[0];
      if (chosen) break;
    }
    if (!chosen) continue;
    picked.push(chosen);
    usedIds.add(chosen.id);
    for (const w of chosen.accept) usedAnswers.add(w);
  }
  return picked;
}

// ---- Tile placement. `placed` holds tile indexes (into the scramble) in slot order, always contiguous. ----

export function placeTile(placed: readonly number[], tile: number, slots: number): number[] {
  if (placed.includes(tile) || placed.length >= slots) return [...placed];
  return [...placed, tile];
}

/** Taking a letter back from slot `slot` shifts the later letters left. */
export function removeSlot(placed: readonly number[], slot: number): number[] {
  return placed.filter((_, i) => i !== slot);
}

export function lettersOf(scramble: string, placed: readonly number[]): string {
  return placed.map((i) => scramble[i] ?? "").join("");
}

export function isCorrect(puzzle: Puzzle, guess: string): boolean {
  return puzzle.accept.includes(guess.toUpperCase());
}

/** 1 point for a word solved with no hint; a hint costs that point; a skip earns nothing. */
export function wordPoints(solved: boolean, usedHint: boolean): number {
  return solved && !usedHint ? 1 : 0;
}
